440	func requiredString(doc map[string]any, field string) (string, error) {
441		v, ok := doc[field]
442		if !ok {
443			return "", fmt.Errorf("缺少必需字段 %q", field)
444		}
445		s, ok := v.(string)
446		if !ok {
447			return "", fmt.Errorf("字段 %q 必须是字符串", field)
448		}
449		if strings.TrimSpace(s) == "" {
450			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
451		}
452		return s, nil
453	}
454	
455	// positiveInt reads a required field as a positive integer. The literal must
456	// be an integral JSON number whose value is representable in full by the Go
457	// int of the running environment: a value beyond math.MaxInt is rejected here
458	// rather than narrowed by an int() conversion, which on a 32-bit environment
459	// could turn 4294967297 into 1 (or a larger value into zero or a negative
460	// number). No truncation, rounding, default substitution or clamping to the
461	// maximum ever happens — such a value is a configuration error regardless of
462	// what int it would collapse into.
463	func positiveInt(doc map[string]any, field string) (int, error) {
464		v, ok := doc[field]
465		if !ok {
466			return 0, fmt.Errorf("缺少必需字段 %q", field)
467		}
468		n, ok := v.(json.Number)
469		if !ok {
470			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
471		}
472		i, err := n.Int64()
473		if err != nil || i <= 0 || i > math.MaxInt {
474			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
475		}
476		return int(i), nil
477	}
